-- Ireme — PostgreSQL schema (Neon).
--
-- Generated by hand from prisma/schema.prisma so it matches what Prisma
-- expects exactly: same table/column names (quoted camelCase), same types,
-- same indexes and foreign-key actions. After running this, `prisma db push`
-- should report the database is already in sync.
--
-- Run it in the Neon console → SQL Editor (target database: neondb), or:
--   psql "$DATABASE_URL" -f prisma/schema.sql
--
-- Tables are created in dependency order; this script is NOT idempotent
-- (it will fail on an already-initialised database rather than drop data).

CREATE TABLE "Meta" (
    "key"   TEXT NOT NULL,
    "value" TEXT NOT NULL,

    CONSTRAINT "Meta_pkey" PRIMARY KEY ("key")
);

CREATE TABLE "School" (
    "id"            TEXT NOT NULL,
    "name"          TEXT NOT NULL,
    "code"          TEXT NOT NULL DEFAULT '',
    "level"         TEXT NOT NULL DEFAULT '',
    "ownership"     TEXT NOT NULL DEFAULT '',
    "province"      TEXT NOT NULL DEFAULT '',
    "district"      TEXT NOT NULL DEFAULT '',
    "sector"        TEXT NOT NULL DEFAULT '',
    "cell"          TEXT NOT NULL DEFAULT '',
    "village"       TEXT NOT NULL DEFAULT '',
    "address"       TEXT NOT NULL DEFAULT '',
    "officialEmail" TEXT NOT NULL DEFAULT '',
    "officialPhone" TEXT NOT NULL DEFAULT '',
    "levels"        TEXT NOT NULL DEFAULT '[]',
    "createdAt"     TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "School_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Class" (
    "id"       TEXT NOT NULL,
    "schoolId" TEXT NOT NULL,
    "name"     TEXT NOT NULL,
    "level"    TEXT,
    "stream"   TEXT,

    CONSTRAINT "Class_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "LearningArea" (
    "id"       TEXT NOT NULL,
    "schoolId" TEXT NOT NULL,
    "name"     TEXT NOT NULL,

    CONSTRAINT "LearningArea_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "User" (
    "id"                 TEXT NOT NULL,
    "schoolId"           TEXT NOT NULL,
    "name"               TEXT NOT NULL,
    "email"              TEXT NOT NULL,
    "phone"              TEXT NOT NULL DEFAULT '',
    "role"               TEXT NOT NULL DEFAULT 'teacher',
    "salt"               TEXT NOT NULL,
    "passwordHash"       TEXT NOT NULL,
    "subjects"           TEXT NOT NULL DEFAULT '[]',
    "classes"            TEXT NOT NULL DEFAULT '[]',
    "language"           TEXT NOT NULL DEFAULT 'en',
    "mustChangePassword" BOOLEAN NOT NULL DEFAULT false,
    "activeYearId"       TEXT,
    "createdAt"          TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "User_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "AcademicYear" (
    "id"        TEXT NOT NULL,
    "schoolId"  TEXT NOT NULL,
    "label"     TEXT NOT NULL,
    "startDate" TEXT NOT NULL,
    "endDate"   TEXT NOT NULL,
    "terms"     TEXT NOT NULL DEFAULT '[1,2,3]',
    "isActive"  BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "AcademicYear_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Plan" (
    "id"             TEXT NOT NULL,
    "schoolId"       TEXT NOT NULL,
    "teacherId"      TEXT NOT NULL,
    "teacherName"    TEXT NOT NULL,
    "academicYearId" TEXT NOT NULL,
    "yearLabel"      TEXT NOT NULL,
    "term"           INTEGER NOT NULL,
    "date"           TEXT NOT NULL,
    "status"         TEXT NOT NULL DEFAULT 'published',
    "approvedByName" TEXT NOT NULL DEFAULT '',
    "approvedAt"     TIMESTAMP(3),
    "createdAt"      TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt"      TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Plan_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "PlanRow" (
    "id"             TEXT NOT NULL,
    "planId"         TEXT NOT NULL,
    "position"       INTEGER NOT NULL,
    "time"           TEXT NOT NULL DEFAULT '',
    "classId"        TEXT NOT NULL DEFAULT '',
    "className"      TEXT NOT NULL DEFAULT '',
    "levelId"        TEXT NOT NULL DEFAULT '',
    "stream"         TEXT,
    "learningAreaId" TEXT NOT NULL DEFAULT '',
    "learningArea"   TEXT NOT NULL DEFAULT '',
    "competence"     TEXT NOT NULL DEFAULT '',
    "procedure"      TEXT NOT NULL DEFAULT '',

    CONSTRAINT "PlanRow_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Lesson" (
    "id"             TEXT NOT NULL,
    "planId"         TEXT NOT NULL,
    "schoolId"       TEXT NOT NULL,
    "teacherId"      TEXT NOT NULL,
    "teacherName"    TEXT NOT NULL DEFAULT '',
    "yearLabel"      TEXT NOT NULL DEFAULT '',
    "academicYearId" TEXT NOT NULL,
    "term"           INTEGER NOT NULL,
    "date"           TEXT NOT NULL,
    "time"           TEXT NOT NULL DEFAULT '',
    "classId"        TEXT NOT NULL DEFAULT '',
    "className"      TEXT NOT NULL DEFAULT '',
    "levelId"        TEXT NOT NULL DEFAULT '',
    "learningAreaId" TEXT NOT NULL DEFAULT '',
    "learningArea"   TEXT NOT NULL DEFAULT '',
    "unit"           TEXT NOT NULL DEFAULT '',
    "competence"     TEXT NOT NULL DEFAULT '',
    "procedure"      TEXT NOT NULL DEFAULT '',
    "createdAt"      TIMESTAMP(3) NOT NULL,
    "updatedAt"      TIMESTAMP(3) NOT NULL,
    "status"         TEXT NOT NULL DEFAULT 'published',

    CONSTRAINT "Lesson_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Session" (
    "token"     TEXT NOT NULL,
    "userId"    TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expiresAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Session_pkey" PRIMARY KEY ("token")
);

-- Unique constraints
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");

-- Indexes
CREATE INDEX "Class_schoolId_idx" ON "Class"("schoolId");
CREATE INDEX "LearningArea_schoolId_idx" ON "LearningArea"("schoolId");
CREATE INDEX "User_schoolId_idx" ON "User"("schoolId");
CREATE INDEX "AcademicYear_schoolId_idx" ON "AcademicYear"("schoolId");
CREATE INDEX "Plan_schoolId_idx" ON "Plan"("schoolId");
CREATE INDEX "Plan_teacherId_idx" ON "Plan"("teacherId");
CREATE INDEX "Plan_academicYearId_idx" ON "Plan"("academicYearId");
CREATE INDEX "Plan_date_idx" ON "Plan"("date");
CREATE INDEX "PlanRow_planId_idx" ON "PlanRow"("planId");
CREATE INDEX "Lesson_schoolId_idx" ON "Lesson"("schoolId");
CREATE INDEX "Lesson_classId_learningAreaId_idx" ON "Lesson"("classId", "learningAreaId");
CREATE INDEX "Lesson_teacherId_idx" ON "Lesson"("teacherId");
CREATE INDEX "Lesson_planId_idx" ON "Lesson"("planId");
CREATE INDEX "Lesson_status_idx" ON "Lesson"("status");
CREATE INDEX "Session_userId_idx" ON "Session"("userId");

-- Foreign keys
ALTER TABLE "Class"
    ADD CONSTRAINT "Class_schoolId_fkey" FOREIGN KEY ("schoolId")
    REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "LearningArea"
    ADD CONSTRAINT "LearningArea_schoolId_fkey" FOREIGN KEY ("schoolId")
    REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "User"
    ADD CONSTRAINT "User_schoolId_fkey" FOREIGN KEY ("schoolId")
    REFERENCES "School"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "AcademicYear"
    ADD CONSTRAINT "AcademicYear_schoolId_fkey" FOREIGN KEY ("schoolId")
    REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Plan"
    ADD CONSTRAINT "Plan_schoolId_fkey" FOREIGN KEY ("schoolId")
    REFERENCES "School"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Plan"
    ADD CONSTRAINT "Plan_teacherId_fkey" FOREIGN KEY ("teacherId")
    REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Plan"
    ADD CONSTRAINT "Plan_academicYearId_fkey" FOREIGN KEY ("academicYearId")
    REFERENCES "AcademicYear"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "PlanRow"
    ADD CONSTRAINT "PlanRow_planId_fkey" FOREIGN KEY ("planId")
    REFERENCES "Plan"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Lesson"
    ADD CONSTRAINT "Lesson_planId_fkey" FOREIGN KEY ("planId")
    REFERENCES "Plan"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Session"
    ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId")
    REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
